Let $d_n:\{0,1,\cdots,\alpha_n\}\to\mathbb{R}_{\geq0}$ be a mapping with $d_n(0)\coloneq 0$ and $d_n(m)>0$ for $m\in\{1,2,\cdots,\alpha_n\}$. A Markov process on the state space $\Omega_n$ is called the symmetric partial exclusion process (or the SPEP for short) if its generator is given by
    \begin{equation}
      L_nf(\eta) \coloneq \frac{1}{c(\alpha_n)}\sum_{x,y\in\mathbb{Z}\,;\,|x-y|=1}c(\eta_x)d_n(\alpha_n-\eta_y)\left[f(\eta^{x,y})-f(\eta) \right]
    \end{equation}
    where $\eta\in\Omega_n$, $f:\Omega_n\to\mathbb{R}$ is a local function\footnote{We say that a function $f:\Omega_n\to\mathbb{R}$ is  \textit{local} if it depends only on a finite number of occupation variables, i.e.  if there exists a finite set $A \subset \mathbb Z$ such that $f (\eta) = f (\tilde\eta )$ for any
$\eta,\tilde\eta\in\Omega_n$ with $\eta(x) = \tilde \eta(x)$ for any $x \in A$. For a local function $f$, the support of $f$, denoted by $\mathrm{supp}(f)$, is defined as the smallest such set.}  and 
    \begin{equation}
      \eta^{x,y}(z)\coloneq
      \begin{cases}
        \eta_x-1\quad &z=x\\
        \eta_y+1\quad &z=y\\
        \eta_z\quad &\text{otherwise}.
      \end{cases}
    \end{equation}

For $m\in\mathbb{N}_0$, define
    \begin{align*}
      c!(m) &\coloneq \begin{cases}
        c(m)c(m-1)\cdots c(1)\quad &m\in\mathbb{N} \\
        1\quad&m=0
      \end{cases}\\
      d_n!(m) &\coloneq \begin{cases}
        d_n(m)d_n(m-1)\cdots d_n(1)\quad &m\in\{1,2,\cdots,\alpha_n\} \\
        1\quad&m=0.
      \end{cases}\\
    \end{align*}

For $\lambda\in[0,\infty)$, we define a product probability measure $\overline{\nu}^{(n)}_\lambda$ on $\Omega_n$ with its common marginal
    \begin{equation}
      \overline{\nu}^{(n)}_\lambda\!\left(\eta_x=m \right)\coloneq \frac{1}{Z^{(n)}_\lambda}\frac{d_n!(\alpha_n)}{c!(m)d_n!(\alpha_n-m)}\lambda^m \quad\text{for }\, m\in\{0,1,\cdots,\alpha_n\},
    \end{equation}
  where
  \begin{equation}
    Z^{(n)}_\lambda\coloneq \sum_{m=0}^{\alpha_n} \frac{d_n!(\alpha_n)}{c!(m)d_n!(\alpha_n-m)}\lambda^m.
  \end{equation}

We say that a stochastic process $\mathcal{X}^{(n)}\in D([0,T]:\mathcal{S}'(\mathbb{R}))$ is the density fluctuation field associated with the SPEP if for any $\phi\in\mathcal{S}(\mathbb{R})$, it holds that
    \begin{equation}
    \mathcal{X}^{(n)}_t(\phi)\coloneq \frac{1}{\sqrt{n}}\sum_{x\in\mathbb{Z}}\left(\eta_x(t)-\rho \right)\phi\!\left(\frac{x}{n}\right).
  \end{equation}

\label{def-sol-SHE}
    An $\mathcal{S}'(\mathbb{R})$-valued continuous process $\{\mathcal{Y}_t\}_{t\in[0,T]}$ is a solution to the SHE \eqref{SHE} if for any $\phi\in C([0,T]:\mathcal{S}(\mathbb{R}))\cap C^1((0,T):\mathcal{S}(\mathbb{R}))$,
    \begin{equation}
      \mathcal{Y}_t(\phi_t)-\mathcal{Y}_0(\phi_0)-\int_0^t\mathcal{Y}_s((\partial_s+D\Delta)\phi_s)\,ds
    \end{equation}
    is a continuous martingale of quadratic variation
    \begin{equation}
      2\chi D \int_0^t\langle\nabla\phi_s,\nabla\phi_s\rangle_{L^2(\mathbb{R})}ds,
    \end{equation}
    where $\phi_t=\phi(t,\cdot)$.

\label{Main-theorem}
  Fix a constant $\rho>0$ arbitrarily and suppose that the initial distribution of $\{\eta(t)\}_{t\in[0,T]}$ is $\nu^{(n)}_\rho$. Then the sequence $\{\mathcal{X}^{(n)}_\cdot \}_{n}$ converges in distribution on $D([0,T]:\mathcal{S}'(\mathbb{R}))$ to the solution of the SHE
  \begin{equation}\label{limit-eqn}
    d\mathcal{Y}_t= D_c^{(\infty)}(\rho)\Delta\mathcal{Y}_tdt + \sqrt{2\Phi_c^{(\infty)}(\rho)}\nabla d\mathcal{B}_t.
  \end{equation}

In the case $a=0$ (i.e. $\alpha_n$ does not depend on $n$), $\Phi_c^{(n)}(\rho)$, $D_c^{(n)}(\rho)$, and $\chi^{(n)}(\rho)$ do not depend on $n$. As shown in \cite{d80477dd344645dc8ca9cb717946fc90}, the scaling limit of fluctuation fields is also the SHE
    \begin{equation}\label{GHS-limit-eq}
      d\mathcal{Y}_t= D_c^{(n)}(\rho)\Delta\mathcal{Y}_tdt + \sqrt{2D_c^{(n)}(\rho)\chi^{(n)}(\rho)}\nabla d\mathcal{B}_t.
    \end{equation}
    We can check that $\Phi_c^{(n)}(\rho)=D_c^{(n)}(\rho)\chi^{(n)}(\rho)$ for any $n\in\mathbb{N}\cup \{\infty\}$ by a direct computation. Therefore, comparing \eqref{limit-eqn} and \eqref{GHS-limit-eq}, we observe that our model interpolates between the SPEP with $a=0$ and the SZRP at the macroscopic level.

\label{lemma-cvgc-part-fct}
    The following two statements hold:
    \begin{itemize}
      \item $Z_\lambda^{(n)}$ and $Z_\lambda^{(\infty)}$ are continuous and strictly increasing in $\lambda$.
      \item $\lim_{n\to\infty} Z_{\lambda/c(\alpha_n)}^{(n)}=Z_{\lambda}^{(\infty)} \quad \text{uniformly on compact sets}.$
    \end{itemize}

The first item is immediate.
    For the second item, 
    \begin{align*}
    Z_{\lambda/c(\alpha_n)}^{(n)}&= \sum_{m=0}^{\alpha_n} \frac{1}{c!(m)}\prod_{i=0}^{m-1}\left(1-\frac{c(i)}{c(\alpha_n)} \right) \lambda^m \\ &\to \sum_{m=0}^{\infty} \frac{1}{c!(m)}\lambda^m =Z_{\lambda}^{(\infty)} \quad \text{as }\, n\to\infty. \\
    \end{align*}
    By using the Weierstrass M-test, we can show that the convergence above is uniform on compact sets.

For the proof that $F_\infty( \lambda)$ is continuous and strictly increasing, see \cite[Section 3]{Kipnis_Landm}.

    Next we consider $F_n(\lambda)$. A straightforward computation yields
    \begin{equation}
      \partial_\lambda F_n\!\left(\lambda \right)=\frac{\operatorname{Var}_{\overline{\nu}^{(n)}_\lambda} \!\left(\eta_x\right)}{\lambda}>0.
    \end{equation}
    Thus $F_n(\lambda)$ is strictly increasing in $\lambda$ and the continuity is obvious.

    Finally, let us prove that $\lim_{n\to\infty}F_n(\lambda)=F_\infty(\lambda)$ uniformly on compact sets. By the definition of $F_n(\lambda)$, 
    \begin{equation}
      F_n(\lambda)=\frac{1}{Z_{\lambda/c(\alpha_n)}^{(n)}}\sum_{m=0}^{\alpha_n}\frac{m}{c!(m)}\prod_{i=0}^{m-1}\left(1-\frac{c(i)}{c(\alpha_n)} \right) \lambda^m.
    \end{equation}
    Therefore we have the statement combining Lemma~\ref{lemma-cvgc-part-fct} and the Weierstrass M-test.

Since $\lambda^{(n)}_\rho$ is increasing in $\rho$, it suffices to show that $\{\lambda^{(n)}_R\,:\alpha_n>R \}$ is a bounded subset.

    \begin{align*}
      \lim_{n\to\infty} F_n\!\left(\lambda^{(\infty)}_{R+1} \right)=F_\infty\!\left(\lambda^{(\infty)}_{R+1}\right)=R+1.
    \end{align*}
    Hence there exists sufficiently large $n_R\in\mathbb{N}$ such that $F_n(\lambda^{(\infty)}_{R+1})>R+\frac{1}{2}$ for any $n\geq n_R$. Therefore we have
    \begin{align*}
      \sup_{n\in\mathbb{N}}\lambda^{(n)}_R\leq \max_{n\leq n_R}\lambda^{(n)}_R \vee \lambda^{(\infty)}_{R+1},
    \end{align*}
    which concludes the proof.

Since $\lambda^{(n)}_\rho$ is increasing in $\rho$, it is enough to check the pointwise convergence. 
    Moreover, since we have Lemma \ref{lemma-cvgc-ev}, it suffices to see
    \begin{equation}
      \lim_{n\to\infty} F_\infty(\lambda^{(n)}_\rho) = F_\infty(\lambda^{(\infty)}_\rho) \quad(=\rho).
    \end{equation}
    By Lemma \ref{lemma-bdd-parameter}, $M_R\coloneq\sup\{\lambda^{(n)}_\rho \mid n\in\mathbb{N}\cup\{\infty\}\text{ with }\alpha_n>R,\,\, \rho\in[0,R]\}<\infty$. Thus
    \begin{align*}
      |F_\infty(\lambda^{(n)}_\rho)-\rho|&= |F_\infty(\lambda^{(n)}_\rho)-F_n(\lambda^{(n)}_\rho)|\\
      &\leq \sup_{\lambda\in[0,M_R]} |F_\infty(\lambda)-F_n(\lambda) |.
    \end{align*}
    The rightmost term tends to 0 thanks to Lemma \ref{lemma-cvgc-ev}.

\label{ev_cvgc}
    Let $f$ be a local function on $\Omega_\infty$ that belongs to $L^1(\overline{\nu}^{(\infty)}_{\lambda})$. Note that $f$ can also be regarded as a local function on $\Omega_n$, and as such belongs to $L^1(\overline{\nu}_{\lambda}^{(n)})$. Then, 
    \begin{align}\label{lem5-cvgc}
    \lim_{n\to\infty}\mathbb{E}_{\,\overline{\nu}^{(n)}_{\lambda}}\!\left[ f\right]=\mathbb{E}_{\,\overline{\nu}^{(\infty)}_{\lambda}}\!\left[ f \right].
    \end{align}
    Moreover, there exists a constant $C>0$ which does not depend on $n$ and $f$ (but may depend on $\lambda$) such that
    \begin{equation}\label{lem5-bound}
      \mathbb{E}_{\,\overline{\nu}^{(n)}_{\lambda}}\!\left[\lvert f\rvert \right]\leq C\mathbb{E}_{\,\overline{\nu}^{(\infty)}_{\lambda}}\!\left[\lvert f\rvert \right]\quad\text{uniformly on compact sets}.
    \end{equation}

Without loss of generality we can assume that $f\geq0$ and $\text{supp}\,\,f\subset \{0,1,\ldots,l-1\}$ for a positive integer $l$.

    Let $I(n,m)\coloneq \prod_{i=0}^{m-1} \left[1-\frac{c(i)}{c(\alpha_n)} \right]$ for $m,n\in\mathbb{N}$ with $n\geq m$ and let
    \begin{align*}
      M\coloneq\sup_{n\in\mathbb{N}}\frac{Z^{(\infty)}_\lambda}{Z^{(n)}_\lambda}.
    \end{align*}
    This is finite since $Z^{(n)}_\lambda\geq1$. Then,
    \begin{equation}
      \begin{split}
        \mathbb{E}_{\,\overline{\nu}^{(n)}_{\lambda}}\!\left[ f \right]=\sum_{\eta_0=0}^{\alpha_n}\sum_{\eta_1=0}^{\alpha_n}\cdots\sum_{\eta_{l-1}=0}^{\alpha_n}f(\eta) \prod_{m=0}^{l-1} \frac{1}{Z^{(n)}_\lambda}\frac{1}{c!(\eta_m)}I(n,m) \lambda^m.
      \end{split}
    \end{equation}
    Here, 
    \begin{equation}\label{lem5-dom}
      0\leq f(\eta) \prod_{m=0}^{l-1} \frac{1}{Z^{(n)}_\lambda}\frac{1}{c!(\eta_m)}I(n,m) \lambda^m
      \leq Mf(\eta) \prod_{m=0}^{l-1} \frac{1}{Z^{(\infty)}_\lambda}\frac{1}{c!(\eta_m)} \lambda^m,
    \end{equation}
    and the dominated convergence theorem yields \eqref{lem5-cvgc}. Moreover, \eqref{lem5-dom} yields the bound \eqref{lem5-bound}.

\label{lemma-cvgc-Phi}
    Let $f\in L^1(\nu^{(\infty)}_\rho)$ be a local function on $\Omega_\infty$. Then we have
    \begin{equation}
      \lim_{n\to\infty}\Phi^{(n)}_{f}(\rho)=\Phi^{(\infty)}_{f}(\rho).
    \end{equation}

\label{lem-chi-times-D-equal-Phi}
    Suppose that $l\in\mathbb{N}$ and $f$ is a local function on $\Omega_n$ with $\operatorname{supp} f\subset \{0,1,\cdots,l-1\}$. Then, for any $\rho\in (0,\alpha_n)$, we have
    \begin{equation}
      \chi^{(n)}(\rho)D^{(n)}_f(\rho)=\operatorname{Cov}_{\nu^{(n)}_\rho}\!\left(f, \sum_{x=0}^{l-1}\eta_x\right).
    \end{equation}

For any $\lambda>0$ and any $m\in\{0,1,\cdots,\alpha_n\}$, we define
    \begin{equation}
      \overline{\Phi}^{(n)}_f(\lambda)\coloneq E_{\overline{\nu}^{(n)}_\lambda}\!\left[f \right]
    \end{equation}
    and
    \begin{equation}
      J(n,m)\coloneq \frac{d_n!(\alpha_n)}{c!(m)d_n!(\alpha_n-m)}.
    \end{equation}
    Then we have
    \begin{align}
      \overline{\Phi}^{(n)}_f(\lambda)=\sum_{\eta_0,\eta_1,\cdots,\eta_{l-1}=0}^{\alpha_n}f(\eta)\prod_{x=0}^{l-1}J(n,\eta_x)\frac{\lambda^{\eta_x}}{Z^{(n)}_\lambda}.
    \end{align}
    Differentiating both sides with respect to $\lambda$, we obtain
    \begin{align}
      \frac{d}{d\lambda}\overline{\Phi}^{(n)}_f(\lambda)&=\sum_{y=0}^{l-1}\sum_{\eta_0,\eta_1,\cdots,\eta_{l-1}=0}^{\alpha_n}f(\eta)\prod_{x\in\{0,1,\cdots,l-1\}\setminus\{y\}}J(n,\eta_x)\frac{\lambda^{\eta_x}}{Z^{(n)}_\lambda}\cdot J(n,\eta_y)\frac{d}{d\lambda}\left(\frac{\lambda^{\eta_y}}{Z^{(n)}_\lambda}\right)\\
      &=\sum_{y=0}^{l-1}\sum_{\eta_0,\eta_1,\cdots,\eta_{l-1}=0}^{\alpha_n}f(\eta)\prod_{x\in\{0,1,\cdots,l-1\}\setminus\{y\}}J(n,\eta_x)\frac{\lambda^{\eta_x}}{Z^{(n)}_\lambda}\cdot J(n,\eta_y)\frac{\eta_y Z^{(n)}_\lambda-\lambda \frac{d}{d\lambda}Z^{(n)}_\lambda}{(Z^{(n)}_\lambda)^2}\lambda^{\eta_y-1}\\
      &=\frac{1}{\lambda}\sum_{y=0}^{l-1}\left\{E_{\overline{\nu}^{(n)}_\lambda}\!\left[f\eta_y \right]-E_{\overline{\nu}^{(n)}_\lambda}\!\left[f \right]E_{\overline{\nu}^{(n)}_\lambda}\!\left[\eta_y \right] \right\}\\
      &=\frac{1}{\lambda}\sum_{y=0}^{l-1}\operatorname{Cov}_{\overline{\nu}^{(n)}_\lambda}\!\left(f,\eta_y \right).\\
      &= \frac{1}{\lambda}\operatorname{Cov}_{\overline{\nu}^{(n)}_\lambda}\!\left(f,\sum_{x=0}^{l-1}\eta_x \right).
    \end{align}
    In the third equality, we used the fact that $E_{\overline{\nu}^{(n)}_\lambda}\!\left[\eta_y \right]=\lambda \frac{d}{d\lambda}Z^{(n)}_\lambda/Z^{(n)}_\lambda$.
    Combining the above with the definition of $D^{(n)}_f(\rho)$, we obtain
    \begin{align}
      D^{(n)}_f(\rho)&=\frac{d}{d\rho}\Phi^{(n)}_f(\rho)\\
      &=\frac{d}{d\rho}\lambda^{(n)}_\rho\frac{d}{d\lambda}\overline{\Phi}^{(n)}_f(\lambda^{(n)}_\rho)\cdot\\
      &=\frac{\lambda^{(n)}_\rho}{\chi^{(n)}(\rho)}\cdot \frac{1}{\lambda^{(n)}_\rho}\operatorname{Cov}_{\overline{\nu}^{(n)}_{\lambda^{(n)}_\rho}}\!\left(f,\sum_{x=0}^{l-1}\eta_x \right)\\
      &=\frac{1}{\chi^{(n)}(\rho)}\operatorname{Cov}_{\nu^{(n)}_\rho}\!\left(f,\sum_{x=0}^{l-1}\eta_x \right).
    \end{align}
    Therefore we have the desired result.

\label{lem-chi-times-D-equal-Phi-infty}
    Suppose that $l\in\mathbb{N}$, $R>0$ and that $f\in L^1(\nu^{(\infty)}_R)$ is a local function with $\text{supp}f\subset\{0,1,\cdots,l-1\}$. Then, for any $\rho\in(0,R)$, 
    \begin{equation}
      \chi^{(\infty)}(\rho)D^{(\infty)}_f(\rho)=\operatorname{Cov}_{\nu^{(\infty)}_\rho}\!\left(f, \sum_{x=0}^{l-1}\eta_x\right).
    \end{equation}

\label{lemma-cvgc-D}
    Suppose that $R>0$ and that $f\in L^1(\nu^{(\infty)}_R)$ is a local function. Then, for any $\rho\in(0,R)$, 
    \begin{equation}
      \lim_{n\to\infty}D_f^{(n)}(\rho)=D_f^{(\infty)}(\rho).
    \end{equation}

\label{BGP}
    For any local function $f\in L^2(\nu^{(\infty)}_\rho)$ and for any $\phi\in C([0,T]:\mathcal{S}(\mathbb{R}))$, 
    \begin{equation}\label{BGP-fml}
    \begin{split}
      \lim_{n\to\infty} \mathbb{E}_n\!\biggl[\,\sup_{t\in[0,T]}& \biggl|\int_0^t \frac{1}{\sqrt{n}}\sum_{x\in\mathbb{Z}}\bigl\{\tau_x f(\eta(s)) \\ 
      &- \Phi_f^{(n)}(\rho) - D^{(n)}_f\!(\rho)\left(\eta_x(s)-\rho \right) \bigr\}\phi\!\left(s,\frac{x}{n} \right)\,ds \biggr|^2 \biggr]= 0,
    \end{split}
    \end{equation}
    where
  \begin{align*}
    \tau_x f(\eta)&\coloneq f(\tau_x \eta)\\
    \tau_x \eta_y &\coloneq \eta_{x+y} \quad\text{for any}\,\,y\in\mathbb{Z}.
  \end{align*}

This proof is due to \cite[Lemma 4.3]{Chang2001} and \cite[Appendix A, Proposition 6.1]{Kipnis_Landm}. 
    By the definition of $\|\cdot\|_{-1,n}$, we have that for any $A>0$,
    \begin{equation}\label{estimate}
      \left<h,g\right>_{\nu^{(n)}_\rho}\leq \frac{A}{2}\|h\|_{1,n} + \frac{1}{2A}\|g\|_{-1,n}.
    \end{equation}
    Since $-n^2L_n$ is a nonnegative self-adjoint operator on $L^2(\nu^{(n)}_\rho)$, $\left(\gamma-n^2L_n\right)^{-1}$ is a bounded operator on $L^2(\nu^{(n)}_\rho)$ for any $\gamma>0$. Thus for any $\gamma>0$ and any $g\in L^2(\nu^{(n)}_\rho)$ with $\lVert g \rVert_{-1,n}<\infty$, there exists $h_\gamma\in L^2(\nu^{(n)}_\rho)$ such that 
    \begin{equation}\label{h_gamma}
      \gamma h_\gamma - n^2L_n h_\gamma = g.
    \end{equation}
    Taking $\left<\cdot,h_\gamma\right>$ on both sides and using the inequality \eqref{estimate} yield
    \begin{align*}
      \gamma \left<h_\gamma,h_\gamma \right>_{\nu^{(n)}_\rho} &\leq \|g\|_{-1,n}^2\\
      \|h_\gamma\|_{1,n}^2&\leq\|g\|_{-1,n}^2.
    \end{align*}
    Using the above formula, we have
    \begin{equation}
      \|g-\left(-n^2L_n\right)h_\gamma\|^2_{L^2(\nu^{(n)}_\rho)}\leq \gamma\|g\|_{-1,n}^2\to0\quad \text{as}\,\,\gamma\searrow0.
    \end{equation}
    Therefore $g$ can be approximated by elements of the range of the operator $L_n$ as long as $\|g\|_{-1,n}<\infty$. 

    Now let us move on to the proof of the Kipnis--Varadhan inequality. In order to prove \eqref{Kipnis--Varadhan}, we can assume that the right-hand side of \eqref{Kipnis--Varadhan} is finite. 
    Suppose that a function $f_\gamma(s,\cdot)$ satisfies
    \begin{equation}
      \gamma f_\gamma(s,\cdot) - n^2L_n f_\gamma(s,\cdot) = f(s,\cdot).
    \end{equation}
    Then we obtain
    \begin{equation}
      \begin{split}
        \mathbb{E}_n\!\left[\sup_{t\in[0,T]}\left|\int_0^t f(s,\eta(s))\,ds \right|^2 \right]&\leq 2\mathbb{E}_n\!\left[\sup_{t\in[0,T]}\left|\int_0^t f(s,\eta(s))+n^2L_nf_\gamma(s,\eta(s)) \,ds \right|^2 \right]\\
        &\quad\quad+2\mathbb{E}_n\!\left[\sup_{t\in[0,T]}\left|\int_0^t n^2L_nf_\gamma(s,\eta(s))\,ds \right|^2 \right]\\
        &\leq 2T\int_0^T \|f(s,\eta(s))+n^2L_nf_\gamma(s,\eta(s))\|_{L^2(\nu^{(n)}_\rho)}^2\,ds\\
        &\quad\quad +2\mathbb{E}_n\!\left[\sup_{t\in[0,T]}\left|\int_0^t n^2L_nf_\gamma(s,\eta(s))\,ds \right|^2 \right]\\
        &\leq 2T\gamma \int_0^T \|f(s,\cdot)\|^2_{-1,n}\,ds\\
        &\quad\quad +2\mathbb{E}_n\!\left[\sup_{t\in[0,T]}\left|\int_0^t n^2L_nf_\gamma(s,\eta(s))\,ds \right|^2 \right].\\
      \end{split}
    \end{equation}
    Since we can take $\gamma>0$ arbitrarily, the first term on the right-hand side will be arbitrarily small. Therefore we only have to take care of the second term.

    We can make use of the Dynkin martingale:
    \begin{equation}
      M_t(\eta)\coloneq f_\gamma(t,\eta(t))-f_\gamma(0,\eta(0))-\int_0^t \left(\partial_s+n^2L_n \right)f_\gamma(s,\eta(s))\,ds.
    \end{equation}
    This is a martingale with respect to the filtration generated by $\{\sigma(\eta(s))\,:\,s\in[0,t] \}$. On the other hand, we have so-called the backward martingale
    \begin{equation}
      M_t^-(\eta)\coloneq f_\gamma(T-t,\eta(T-t))-f_\gamma(T,\eta(T)) -\int_0^t \left(-\partial_s+n^2L_n^* \right)f_\gamma(T-s,\eta(T-s))\,ds
    \end{equation}
    In the above expression, $\partial_s$ denotes the derivative with respect to the first argument of the operand (not with respect to the variable $s$) and $L_n^*$ is the adjoint operator on $L^2(\nu^{(n)}_\rho)$ (in this case $L_n^*=L_n$). This is a $\{\sigma(\eta(s))\,:\,s\in[t,T]\}$-martingale.
    Changing variables in the integral in the backward martingale yields
    \begin{equation}
      M_T^--M_{T-t}^- = f_\gamma(0,\eta(0))-f_\gamma(t,\eta(t))-\int_0^t (-\partial_s+n^2L_n)f_\gamma(s,\eta(s))\,ds.
    \end{equation}
    Then
    \begin{equation}
      M_t+M_T^--M_{T-t}^-=2\int_0^t n^2L_n f_\gamma(s,\eta(s))\,ds.
    \end{equation}
    Therefore
    \begin{equation}\label{rewriting-LHS-KVineq}
      \mathbb{E}_n\!\left[\sup_{t\in[0,T]}\left|\int_0^t n^2L_nf_\gamma(s,\eta(s))\,ds \right|^2 \right]=\frac{1}{4}\mathbb{E}_n\!\left[\sup_{t\in[0,T]}\left(M_t+M_T^--M_{T-t}^- \right)^2 \right].
    \end{equation}
    By Doob's inequality and an elementary inequality $(a_1+a_2+a_3)^2\leq3(a_1^2+a_2^2+a_3^2)$, the right-hand side of \eqref{rewriting-LHS-KVineq} is bounded from above by
    \begin{equation}
      \mathbb{E}_n\!\left[3\left<M\right>_T + \frac{15}{4}\left<M^-\right>_T \right],
    \end{equation}
    where $\left<M \right>_\cdot$ denotes the quadratic variation. We can check that 
    \begin{equation}
    \begin{split}
      \mathbb{E}_n\left[\left<M \right>_T \right]&=\mathbb{E}_n\left[\left<M^- \right>_T \right] \\
      &= 2\int_0^T \|f_\gamma(s,\cdot)\|_{1,n}^2\,ds\\
      &\leq 2\int_0^T \|f(s,\cdot)\|_{-1,n}^2\,ds.\\
    \end{split}
    \end{equation}
    Thus we obtain
    \begin{equation}
      \mathbb{E}_n\!\left[\sup_{t\in[0,T]}\left|\int_0^t n^2L_nf_\gamma(s,\eta(s))\,ds \right|^2 \right]\leq \frac{27}{2}\int_0^T \|f(s,\cdot)\|_{-1,n}^2\,ds,
    \end{equation}
    which completes the proof.

The Schwartz space is the function space
    \begin{equation}
      \mathcal{S}(\mathbb{R}^n)\coloneq \left\{f\in C^\infty(\mathbb{R}^n)\,:\, \forall m\in\mathbb{N}_0,\, \|f\|_m<\infty \right\},
    \end{equation}
    where the seminorm $\|\cdot\|_m$ is given by
    \begin{equation}
      \|f\|_m\coloneq \sup_{\substack{\alpha=(\alpha_1,\cdots,\alpha_n)\in\mathbb{N}_0^n\\ \alpha_1+\cdots+\alpha_n\leq m}}\, \sup_{x\in\mathbb{R}^n} (1+|x|^2)^\frac{m}{2} |\partial^\alpha f(x)|.
    \end{equation}
    The space $\mathcal{S}(\mathbb{R}^n)$ is equipped with the seminorm topology induced by $\{\|\cdot\|_m \}_{m\in\mathbb{N}_0}$. It is known that $\mathcal{S}(\mathbb{R}^n)$ is a Polish space.

An $\mathcal{S}'(\mathbb{R})$-valued random variable $\mathcal{W}$ is called the white noise with mean 0 and variance $\chi$ if for any $l\in\mathbb{N}$ and any $\phi_1,\phi_2,\cdots,\phi_l\in\mathcal{S}(\mathbb{R})$, $\left\{\mathcal{W}(\phi_1),\cdots,\mathcal{W}(\phi_l) \right\}$ is a mean-zero Gaussian random vector with covariances given by
    \begin{equation}
      E\!\left[\mathcal{W}(\phi_i)\mathcal{W}(\phi_j) \right]=\chi \langle\phi_i,\phi_j\rangle_{L^2(\mathbb{R})}.
    \end{equation}

$C([0,T]:\mathcal{S}'(\mathbb{R}^n))$ is the space of continuous functions from $[0,T]$ to $\mathcal{S}'(\mathbb{R}^n)$ equipped with the topology induced by a family of seminorms $q_K$ indexed by compact subsets $K \subset \mathcal{S}(\mathbb{R}^n)$.
    \begin{equation}
      q_K\colon C([0,T]:\mathcal{S}'(\mathbb{R}^n))\ni f\mapsto \sup_{t\in[0,T]}p_K\!\left(f(t)\right)\in\mathbb{R}.
    \end{equation}
